/// <summary>
/// Transfer order load planning aid report
/// </summary>
[SRSReportParameterAttribute(classstr(METTransferOrderLoadPlanningAidContract))]
class METTransferOrderLoadPlanningAidDP extends SrsReportDataProviderPreProcessTempDB
{
    METTransferOrderLoadPlanningAidLinesTmp transferOrderLoadPlanningAidLinesTmp;
    METTransferOrderLoadPlanningAidContract contract;
    InventTransferId                        selectedTransferId;
    RecordInsertList                        transferOrdLoadPlanningLinesList;
    CreatedDateTime                         reportGeneratedDateTime;
    InventLocationId                        inventLocationTo, inventLocationFrom;
    SalesShippingDateConfirmed              confirmedShipDateFrom;
    SalesShippingDateRequested              confirmedShipDateTo;
    METRoute                                routeId;
    LogisticsLocationRoleRecId              roleDeliveryRecId;
    InventLocationId                        fromWarehouse;
    InventLocationId                        toWarehouse;
    InventTransferShipDate                  shippingDateFrom;
    InventTransferShipDate                  shippingDateTo;
    METOrderSplitGroup                      orderSplitGroup;
    METOrderExtractStatus                   extractStatus;

}

Method.Source:
/// <summary>
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningAidLinesTmp))]
public METTransferOrderLoadPlanningAidLinesTmp getLines()
{
    select transferOrderLoadPlanningAidLinesTmp;
    return transferOrderLoadPlanningAidLinesTmp;
}

/// <summary>
///    Parses the report parameters and fills the <c>transferOrderLoadPlanningAidLinesTmp</c> tables with data.
/// </summary>
public void processReport()
{
    contract = this.parmDataContract() as METTransferOrderLoadPlanningAidContract;
    transferOrdLoadPlanningLinesList = new RecordInsertList(tableNum(METTransferOrderLoadPlanningAidLinesTmp), true, true, true, true, true, transferOrderLoadPlanningAidLinesTmp);

    routeId = contract.parmRouteID();
    confirmedShipDateFrom = contract.parmConfirmedShipDateFrom();
    confirmedShipDateTo = contract.parmConfirmedShipDateTo();
    orderSplitGroup     = contract.parmOrderSplitGroup();
    extractStatus       = contract.parmExtractStatus();
    fromWarehouse       = contract.parmFromWarehouse();
    toWarehouse         = contract.parmToWarehouse();

    reportGeneratedDateTime = DateTimeUtil::getSystemDateTime();
    roleDeliveryRecId = LogisticsLocationRole::findByName(METConstants::DeliveryAddress).RecId;
    str extractOrdersSelected = contract.parmSelectedRecords();

    if (strLen(extractOrdersSelected) > 0)
    {
        container transferIdCon = str2con(extractOrdersSelected, ',');
        int conLen = conLen(transferIdCon);
        int counter;

        for (counter = 1; counter <= conLen; counter++)
        {
            selectedTransferId = conPeek(transferIdCon, counter);
            this.insertTransferOrders();
        }
    }
    else
    {
        this.insertTransferOrders();
    }

    transferOrdLoadPlanningLinesList.insertDatabase();
}

/// <summary>
/// Insert Transfer orders
/// </summary>
public void insertTransferOrders()
{
    InventTransferTable         inventTransferTable;
    InventTransferLine          inventTransferLine;
    METInventTransferTableExt   metInventTransferTableExt;
    METInventTransferLine       metInventTransferLine;
    MetReqItemTable             metReqItemTable;
    InventLocation              inventLocation, toInventLocation;
    METInventLocation           metInventLocation, toMetInventLocation;
    ReqItemTable                reqItemTable;
    InventDim                   inventDim;
    InventDim                   inventDimReq;
    METIndustryKeyTable         industryKeyTable;

    while select InventDimId, ItemId, TransferId, RecId from inventTransferLine
        join TransferId, ShipDate, InventLocationIdFrom, InventLocationIdTo, CreatedDateTime, RecId from inventTransferTable
            where inventTransferTable.TransferId == inventTransferLine.TransferId
            && (!selectedTransferId || inventTransferTable.TransferId == selectedTransferId)
            && (!fromWarehouse  || inventTransferTable.InventLocationIdFrom == fromWarehouse)
            && (!toWarehouse  || inventTransferTable.InventLocationIdTo == toWarehouse)
            && (inventTransferTable.ShipDate >= confirmedShipDateFrom
            && inventTransferTable.ShipDate <= confirmedShipDateTo)
            && inventTransferTable.TransferStatus == InventTransferStatus::Created
        join Route, RouteStopNum, OrderSplitGroup from metInventTransferTableExt
            where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
            && (!routeId || metInventTransferTableExt.Route == routeId)
            && (!orderSplitGroup || metInventTransferTableExt.OrderSplitGroup == orderSplitGroup)
            && (!extractStatus || metInventTransferTableExt.OrderExtractStatus == extractStatus)
        join Cases, BrokenCase, TotalWeight, TotalVolume from metInventTransferLine
            where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
        join InventSiteId, InventLocationId, inventDimId from inventDim
            where inventDim.inventDimId == inventTransferLine.InventDimId
        join Name, METWHSubEntity, RecId from inventLocation
            where inventLocation.InventLocationId == inventTransferTable.InventLocationIdFrom
        join WHSPalletVolume from metInventLocation
            where metInventLocation.InventLocation == inventLocation.RecId
        join RecId, InventLocationId, Name from toInventLocation
            where toInventLocation.InventLocationId == inventTransferTable.InventLocationIdTo
        join InternalCustomer from toMetInventLocation
            where toMetInventLocation.InventLocation == toInventLocation.RecId
        join CompanyName from industryKeyTable
            where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity
    {
        transferOrderLoadPlanningAidLinesTmp.CompanyName = industryKeyTable.CompanyName;
        transferOrderLoadPlanningAidLinesTmp.FromWareHouseName = inventLocation.Name;
        transferOrderLoadPlanningAidLinesTmp.ReportGeneratedDateTime = reportGeneratedDateTime;
        transferOrderLoadPlanningAidLinesTmp.Route = metInventTransferTableExt.Route;
        transferOrderLoadPlanningAidLinesTmp.DeliveryDate = inventTransferTable.ShipDate;

        transferOrderLoadPlanningAidLinesTmp.TransferId = inventTransferTable.TransferId;
        transferOrderLoadPlanningAidLinesTmp.RouteStop = metInventTransferTableExt.RouteStopNum;
        transferOrderLoadPlanningAidLinesTmp.Cases = metInventTransferLine.Cases;
        transferOrderLoadPlanningAidLinesTmp.Eaches = metInventTransferLine.BrokenCase;
        transferOrderLoadPlanningAidLinesTmp.Weight = metInventTransferLine.TotalWeight;
        transferOrderLoadPlanningAidLinesTmp.Cube = metInventTransferLine.TotalVolume;

        if (metInventLocation.WHSPalletVolume > 0)
        {
            transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube / metInventLocation.WHSPalletVolume;
        }
        else
        {
            transferOrderLoadPlanningAidLinesTmp.Pallets = transferOrderLoadPlanningAidLinesTmp.Cube;
        }

        transferOrderLoadPlanningAidLinesTmp.OrderCreatedDateTime = inventTransferTable.CreatedDateTime;
        transferOrderLoadPlanningAidLinesTmp.OrderSplitCategoryCode = metInventTransferTableExt.OrderSplitGroup;

        transferOrderLoadPlanningAidLinesTmp.ToWarehouseNumber = toMetInventLocation.InternalCustomer;
        transferOrderLoadPlanningAidLinesTmp.ToWareHouseName = DirPartyTable::getName(CustTable::find(toMetInventLocation.InternalCustomer).Party);
        transferOrdLoadPlanningLinesList.add(transferOrderLoadPlanningAidLinesTmp);
    }
}
